(() => {
  const icon = name => `<svg class="icon" aria-hidden="true"><use href="assets/icons.svg#${name}"></use></svg>`;
  const toast = message => { document.querySelector('.toast')?.remove(); const node=document.createElement('div'); node.className='toast'; node.role='status'; node.textContent=message; document.body.append(node); setTimeout(()=>node.remove(),2400); };
  const close = () => document.querySelector('.overlay')?.remove();
  const modal = (html,large=false) => { close(); const node=document.createElement('div'); node.className='overlay'; node.innerHTML=`<section class="dialog${large?' large':''}" role="dialog" aria-modal="true"><button class="round close" aria-label="Закрыть">${icon('close')}</button>${html}</section>`; document.body.append(node); node.querySelector('.close').onclick=close; node.onclick=e=>{if(e.target===node)close()}; node.querySelector('input,button:not(.close)')?.focus(); };
  const views=['dictionary','translator','camera','quiz','lessons','tests','progress','games'];
  const labels={dictionary:['book','Словарь','Слова, формы и примеры'],translator:['translate','Переводчик','Перевод целых текстов'],camera:['camera','Решить по фото','Разбор задачи по шагам'],quiz:['game','Викторины','Соло и с друзьями'],lessons:['book','Уроки','Теория и практика'],tests:['check','Тесты','Проверка знаний'],progress:['chart','Прогресс','Результаты и темы'],games:['game','Развивающие игры','Скоро в DamuLab']};
  const shared=document.querySelector('[data-shared-views]');
  if(shared) shared.innerHTML=`
    <section class="view" data-view="services"><div class="heading"><div><h1>Все сервисы</h1><p>Инструменты для учёбы, языков и игры.</p></div></div><div class="catalog">${views.map((v,i)=>`<button class="service ${['','teal','coral','violet','amber'][i%5]}" data-service="${v}"><span class="service-icon">${icon(labels[v][0])}</span><strong>${labels[v][1]}</strong><span>${labels[v][2]}</span></button>`).join('')}</div></section>
    <section class="view" data-view="dictionary"><div class="heading"><div><h1>Словарь</h1><p>Казахско-русский и русско-казахский.</p></div></div><div class="inner"><section class="panel"><div class="direction"><strong data-direction>Қазақша → Русский</strong><button data-swap aria-label="Поменять направление">${icon('swap')}</button></div><label class="label" for="word">Слово или его часть</label><div class="search">${icon('search')}<input id="word" data-dictionary-input autocomplete="off" placeholder="Например, білім"><div class="suggestions" data-suggestions hidden></div></div><article class="word-result" data-word-result><div class="word-head"><div><h2>білім</h2><p>знание, образование</p></div><span class="tag">существительное</span></div><div class="example"><strong>терең білім</strong><span>глубокие знания</span></div><div class="example"><strong>білім алу</strong><span>получать образование</span></div></article></section><aside class="panel"><h2>Недавно искали</h2><div class="lesson"><span class="lesson-no">KZ</span><div><strong>жетістік</strong><span>достижение</span></div></div><div class="lesson"><span class="lesson-no">RU</span><div><strong>развитие</strong><span>даму</span></div></div><p>Если слова нет в базе, DamuLab предложит AI-перевод с понятной пометкой.</p></aside></div></section>
    <section class="view" data-view="translator"><div class="heading"><div><h1>Переводчик</h1><p>Для фраз, заданий и больших текстов.</p></div></div><section class="panel"><div class="direction"><strong data-direction>Русский → Қазақша</strong><button data-swap aria-label="Поменять направление">${icon('swap')}</button></div><div class="translate-boxes"><div class="translate-box"><textarea data-source placeholder="Введите текст">Знание — это сила, которая открывает человеку дорогу.</textarea><div class="count" data-count>58 / 3000</div></div><div class="translate-box" data-output>Білім — адамға жол ашатын күш.</div></div><div class="room-actions"><button class="primary" data-demo="Перевод скопирован">Скопировать</button><button class="secondary" data-demo="Текст озвучивается">Прослушать</button></div></section></section>
    <section class="view" data-view="camera"><div class="heading"><div><h1>Решить по фото</h1><p>Сфотографируй задачу — получишь объяснение, а не только ответ.</p></div></div><section class="panel"><div class="upload" data-upload-zone><div><span class="service-icon">${icon('camera')}</span><strong>Добавь фотографию задачи</strong><p>Сделай снимок или выбери файл из галереи.</p><button class="primary" data-upload>Попробовать на примере</button></div></div></section></section>
    <section class="view" data-view="quiz"><div class="heading"><div><h1>Играть и учиться</h1><p>Выбери формат — правила понятны из одного предложения.</p></div><button class="linkbtn" data-room>Войти по коду</button></div><section class="panel"><h2>Во что играем?</h2><div class="quiz-modes"><button class="quiz-mode selected"><strong>Переведи слово</strong><span>Выбери перевод до конца таймера.</span></button><button class="quiz-mode"><strong>Верю — не верю</strong><span>Определи, верно ли утверждение.</span></button><button class="quiz-mode"><strong>Классический тест</strong><span>Отвечай и набирай баллы.</span></button></div><div class="room-actions"><button class="primary" data-create-room>Создать комнату</button><button class="secondary" data-room>${icon('qr')} Войти по QR или коду</button></div></section></section>
    <section class="view" data-view="lessons"><div class="heading"><div><h1>Уроки</h1><p>Продолжай начатое или выбери предмет.</p></div></div><div class="catalog"><article class="catalog-card"><span class="tag">Математика</span><h3>Дроби и части</h3><p>Пройдено 62% · осталось 12 минут</p><button class="linkbtn" data-demo="Открываем урок">Продолжить →</button></article><article class="catalog-card"><span class="tag">Қазақ тілі</span><h3>Сын есім</h3><p>Новый урок · 15 минут</p><button class="linkbtn" data-demo="Открываем урок">Начать →</button></article><article class="catalog-card"><span class="tag">Физика</span><h3>Сила и движение</h3><p>3 коротких раздела</p><button class="linkbtn" data-demo="Открываем урок">Начать →</button></article></div></section>
    <section class="view" data-view="progress"><div class="heading"><div><h1>Мой прогресс</h1><p>Что получается и куда двигаться дальше.</p></div></div><div class="grid2"><section class="panel"><h2>Сильные темы</h2><div class="lesson"><span class="lesson-no">92</span><div><strong>Словарный запас</strong><span>Отличный результат</span></div></div><div class="lesson"><span class="lesson-no">81</span><div><strong>Уравнения</strong><span>Уверенное знание</span></div></div></section><aside class="panel"><h2>Общий прогресс</h2><div class="ring"><strong>68%</strong></div></aside></div></section>`;
  if(shared) shared.insertAdjacentHTML('beforeend', `<section class="view" data-view="tests"><div class="heading"><div><h1>Тесты</h1><p>Короткая проверка знаний без лишних инструкций.</p></div></div><div class="catalog"><article class="catalog-card"><span class="tag">5 вопросов</span><h3>Дроби и части</h3><p>Математика · около 4 минут</p><button class="linkbtn" data-demo="Запускаем тест">Начать →</button></article><article class="catalog-card"><span class="tag">8 вопросов</span><h3>Сын есім</h3><p>Қазақ тілі · около 6 минут</p><button class="linkbtn" data-demo="Запускаем тест">Начать →</button></article></div></section><section class="view" data-view="games"><div class="heading"><div><h1>Развивающие игры</h1><p>Новый раздел DamuLab — скоро.</p></div></div><section class="panel"><h2>Тренируй память, внимание и язык</h2><p>Игры появятся в этом каталоге и не потребуют отдельного пункта в основном меню.</p><button class="secondary" data-demo="Сообщим, когда игры появятся">Сообщить о запуске</button></section></section>`);
  const allServices=()=>modal(`<h2>Все сервисы</h2><p>Учёба, языки и игры в одном месте.</p><div class="all-services">${views.map(v=>`<button data-target="${v}">${icon(labels[v][0])}<span>${labels[v][1]}<small>${labels[v][2]}</small></span></button>`).join('')}</div>`,true);
  const go=name=>{const actual=document.querySelector(`[data-view="${name}"]`)?name:'services';document.querySelectorAll('[data-view]').forEach(v=>v.classList.toggle('active',v.dataset.view===actual));document.querySelectorAll('[data-nav]').forEach(v=>v.classList.toggle('active',v.dataset.nav===actual));close();scrollTo({top:0,behavior:'smooth'})};
  document.addEventListener('click',e=>{
    const nav=e.target.closest('[data-nav]'); if(nav)go(nav.dataset.nav);
    const service=e.target.closest('[data-service]'); if(service)go(service.dataset.service);
    const target=e.target.closest('[data-target]'); if(target)go(target.dataset.target);
    if(e.target.closest('[data-all]'))allServices();
    const lang=e.target.closest('[data-lang]'); if(lang){document.querySelectorAll('[data-lang]').forEach(b=>b.classList.toggle('active',b===lang));toast(lang.dataset.lang==='kk'?'Интерфейс: қазақша':'Язык: русский')}
    if(e.target.closest('[data-swap]')){document.querySelectorAll('[data-direction]').forEach(n=>{const a=n.textContent.trim().split(' → ');if(a.length===2)n.textContent=`${a[1]} → ${a[0]}`});const s=document.querySelector('[data-source]'),o=document.querySelector('[data-output]');if(s&&o)[s.value,o.textContent]=[o.textContent.trim(),s.value]}
    if(e.target.closest('[data-upload]')){const z=document.querySelector('[data-upload-zone]');if(z)z.innerHTML=`<div><span class="service-icon" style="margin:0 auto 12px;background:#dcf3e8;color:#167451">${icon('check')}</span><strong>Задача распознана</strong><p>«В классе 28 учеников. 3/7 класса…»</p><button class="primary" data-reveal>Показать объяснение</button><div class="solution" data-solution hidden><div class="step"><b>1</b><div><strong>Находим одну седьмую</strong><p>28 ÷ 7 = 4 ученика.</p></div></div><div class="step"><b>2</b><div><strong>Умножаем на три</strong><p>4 × 3 = 12 учеников — это ответ.</p></div></div></div></div>`}
    if(e.target.closest('[data-reveal]')){document.querySelector('[data-solution]')?.removeAttribute('hidden');e.target.closest('[data-reveal]').hidden=true}
    if(e.target.closest('[data-room]'))modal(`<h2>Войти в комнату</h2><p>Наведите камеру на QR-код друга или введите пятизначный код.</p><div class="qr-grid" aria-label="Демонстрационный QR-код">${icon('qr')}</div><label class="label" for="room-code">Код комнаты</label><div class="search"><input class="code" id="room-code" inputmode="numeric" maxlength="5" placeholder="•••••"></div><button class="primary" style="width:100%;margin-top:11px" data-join>Присоединиться</button>`);
    if(e.target.closest('[data-join]')){const v=document.querySelector('#room-code')?.value||'';if(!/^\d{5}$/.test(v))return toast('Введите 5 цифр кода комнаты');close();toast(`Подключаемся к комнате ${v}`)}
    if(e.target.closest('[data-create-room]'))modal(`<h2>Комната готова</h2><p>Покажите экран друзьям. Код состоит только из цифр.</p><div class="qr-grid">${icon('qr')}</div><div style="text-align:center;font:800 2rem Manrope">48217</div><button class="primary" style="width:100%;margin-top:16px" data-demo="Игра начинается">Начать игру</button>`);
    const mode=e.target.closest('.quiz-mode');if(mode){document.querySelectorAll('.quiz-mode').forEach(n=>n.classList.toggle('selected',n===mode));toast(`Выбрано: ${mode.querySelector('strong').textContent}`)}
    const zoom=e.target.closest('[data-image-zoom]');if(zoom){const box=document.createElement('div');box.className='image-lightbox';box.innerHTML=`<button class="round" type="button" aria-label="Закрыть изображение">${icon('close')}</button><img src="${zoom.dataset.imageZoom}" alt="Увеличенное изображение из лекции">`;document.body.append(box);box.querySelector('button').onclick=()=>box.remove();box.onclick=event=>{if(event.target===box)box.remove()}}
    const demo=e.target.closest('[data-demo]');if(demo)toast(demo.dataset.demo||'Действие показано в прототипе');
  });
  document.addEventListener('keydown',e=>{if(e.key==='Escape'){close();document.querySelector('.image-lightbox')?.remove()}});
  const input=document.querySelector('[data-dictionary-input]'),suggestions=document.querySelector('[data-suggestions]');
  input?.addEventListener('input',()=>{if(!input.value.trim())return suggestions.hidden=true;suggestions.innerHTML=['білім — знание','білімді — знающий','білім беру — образование'].map(x=>`<button data-word="${x.split(' — ')[0]}">${x}</button>`).join('');suggestions.hidden=false});
  suggestions?.addEventListener('click',e=>{const w=e.target.closest('[data-word]');if(!w)return;input.value=w.dataset.word;suggestions.hidden=true;document.querySelector('[data-word-result]')?.removeAttribute('hidden')});
  const source=document.querySelector('[data-source]');source?.addEventListener('input',()=>{document.querySelector('[data-count]').textContent=`${source.value.length} / 3000`;clearTimeout(source.timer);source.timer=setTimeout(()=>document.querySelector('[data-output]').textContent=source.value.trim()?'Білім — адамға жол ашатын күш. Бұл — аударма үлгісі.':'Перевод появится здесь',280)});

  const smartQuery=document.querySelector('[data-smart-query]');
  const smartSuggestions=document.querySelector('[data-smart-suggestions]');
  const showSmartAnswer=()=>{
    if(!smartQuery?.value.trim()) return toast('Напиши вопрос или тему для поиска');
    smartSuggestions?.setAttribute('hidden','');
    document.querySelector('[data-smart-answer]')?.removeAttribute('hidden');
    document.querySelector('[data-smart-answer]')?.scrollIntoView({behavior:'smooth',block:'nearest'});
  };
  smartQuery?.addEventListener('input',()=>{
    const value=smartQuery.value.trim();
    if(!value){smartSuggestions.hidden=true;return;}
    const variants=['как найти площадь треугольника','как найти высоту треугольника','площадь прямоугольного треугольника'];
    smartSuggestions.innerHTML=variants.map(item=>`<button type="button" data-smart-suggestion="${item}">${item}</button>`).join('');
    smartSuggestions.hidden=false;
  });
  smartQuery?.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();showSmartAnswer()}});
  document.querySelector('[data-smart-submit]')?.addEventListener('click',showSmartAnswer);
  smartSuggestions?.addEventListener('click',event=>{const item=event.target.closest('[data-smart-suggestion]');if(!item)return;smartQuery.value=item.dataset.smartSuggestion;showSmartAnswer()});
  document.querySelectorAll('[data-smart-fill]').forEach(button=>button.addEventListener('click',()=>{smartQuery.value=button.dataset.smartFill;smartQuery.focus();smartQuery.dispatchEvent(new Event('input'))}));
})();
